 "$p"; elif ln -- "$w" "$p" 2>/dev/null; then if [ "$p" -ef "$w" ]; then printf 'U/%s\n' "$p"; else rm -f -- "$p/${w##*/}"; printf 'C/%s\n' "$p"; fi; elif [ -e "$p" ] || [ -L "$p" ]; then printf 'C/%s\n' "$p"; else f; fi; rm -f -- ${w:+"$w"} ${o:+"$o"}; w=; o=; done < "$t/expect"